Creating a Client-side Program If all you need to do is have your robot program communicate with a COTS coprocessor or a dashboard running on the Driver Station laptop, then the previous examples of writing robot programs are sufficient. But if you would like to write some custom client code that would run on the drivers station or on a coprocessor then you need to know how to build NetworkTables programs for those (non-roboRIO) platforms. A basic client program looks like the following example. Java import edu.wpi.first.networktables.DoubleSubscriber ; import edu.wpi.first.networktables.NetworkTable ; import edu.wpi.first.networktables.NetworkTableInstance ; import edu.wpi.first.networktables.NetworkTablesJNI ; import edu.wpi.first.util.CombinedRuntimeLoader ; import java.io.IOException ; import edu.wpi.first.cscore.CameraServerJNI ; import edu.wpi.first.math.WPIMathJNI ; import edu.wpi.first.util.WPIUtilJNI ; public class Program { public static void main ( String [] args ) throws IOException { NetworkTablesJNI . Helper . setExtractOnStaticLoad ( false ); WPIUtilJNI . Helper . setExtractOnStaticLoad ( false ); WPIMathJNI . Helper . setExtractOnStaticLoad ( false ); CameraServerJNI . Helper . setExtractOnStaticLoad ( false ); CombinedRuntimeLoader . loadLibraries ( Program . class , "wpiutiljni" , "wpimathjni" , "ntcorejni" , Core . NATIVE_LIBRARY_NAME , "cscorejni" ); new Program (). run (); } public void run () { NetworkTableInstance inst = NetworkTableInstance . getDefault (); NetworkTable table = inst . getTable ( "datatable" ); DoubleSubscriber xSub = table . getDoubleTopic ( "x" ). subscribe ( 0.0 ); DoubleSubscriber ySub = table . getDoubleTopic ( "y" ). subscribe ( 0.0 ); inst . startClient4 ( "example client" ); inst . setServerTeam ( TEAM ); // where TEAM=190, 294, etc, or use inst.setServer("hostname") or similar inst . startDSClient (); // recommended if running on DS computer; this gets the robot IP from the DS while ( true ) { try { Thread . sleep ( 1000 ); } catch ( InterruptedException ex ) { System . out . println ( "interrupted" ); return ; } double x = xSub . get (); double y = ySub . get (); System . out . println ( "X: " + x + " Y: " + y ); } } } C++ #include <chrono> #include <thread> #include <fmt/format.h> #include <networktables/NetworkTableInstance.h> #include <networktables/NetworkTable.h> #include <networktables/DoubleTopic.h> int main () { auto inst = nt :: NetworkTableInstance :: GetDefault (); auto table = inst . GetTable ( "datatable" ); auto xSub = table -> GetDoubleTopic ( "x" ). Subscribe ( 0.0 ); auto ySub = table -> GetDoubleTopic ( "y" ). Subscribe ( 0.0 ); inst . StartClient4 ( "example client" ); inst . SetServerTeam ( TEAM ); // where TEAM=190, 294, etc, or use inst.setServer("hostname") or similar inst . StartDSClient (); // recommended if running on DS computer; this gets the robot IP from the DS while ( true ) { using namespace std :: chrono_literals ; std :: this_thread :: sleep_for ( 1 s ); double x = xSub . Get (); double y = ySub . Get (); fmt :: print ( "X: {} Y: {} 
 " , x , y ); } } C++ (Handle-based) #include <chrono> #include <thread> #include <fmt/format.h> #include <wpi/nt/ntcore_cpp.hpp> int main () { NT_Inst inst = nt :: GetDefaultInstance (); NT_Subscriber xSub = nt :: Subscribe ( nt :: GetTopic ( inst , "/datatable/x" ), NT_DOUBLE , "double" ); NT_Subscriber ySub = nt :: Subscribe ( nt :: GetTopic ( inst , "/datatable/y" ), NT_DOUBLE , "double" ); nt :: StartClient4 ( inst , "example client" ); nt :: SetServerTeam ( inst , TEAM , 0 ); // where TEAM=190, 294, etc, or use inst.setServer("hostname") or similar nt :: StartDSClient ( inst , 0 ); // recommended if running on DS computer; this gets the robot IP from the DS while ( true ) { using namespace std :: chrono_literals ; std :: this_thread :: sleep_for ( 1 s ); double x = nt :: GetDouble ( xSub , 0.0 ); double y = nt :: GetDouble ( ySub , 0.0 ); fmt :: print ( "X: {} Y: {} 
 " , x , y ); } } C #include <stdio.h> #include <threads.h> #include <time.h> #include <networktables/wpi/nt/ntcore.h> int main () { NT_Instance inst = NT_GetDefaultInstance (); NT_Subscriber xSub = NT_Subscribe ( NT_GetTopic ( inst , "/datatable/x" ), NT_DOUBLE , "double" , NULL , 0 ); NT_Subscriber ySub = NT_Subscribe ( NT_GetTopic ( inst , "/datatable/y" ), NT_DOUBLE , "double" , NULL , 0 ); NT_StartClient4 ( inst , "example client" ); NT_SetServerTeam ( inst , TEAM ); // where TEAM=190, 294, etc, or use inst.setServer("hostname") or similar NT_StartDSClient ( inst ); // recommended if running on DS computer; this gets the robot IP from the DS while ( true ) { thrd_sleep ( & ( struct timespec ){. tv_sec = 1 }, NULL ); double x = NT_GetDouble ( xSub , 0.0 ); double y = NT_GetDouble ( ySub , 0.0 ); printf ( "X: %f Y: %f 
 " , x , y ); } } Python #!/usr/bin/env python3 import ntcore import time if __name__ == "__main__" : inst = ntcore . NetworkTableInstance . get_default () table = inst . get_table ( "datatable" ) x_sub = table . get_double_topic ( "x" ) . subscribe ( 0 ) y_sub = table . get_double_topic ( "y" ) . subscribe ( 0 ) inst . start_client4 ( "example client" ) inst . set_server_team ( TEAM ) # where TEAM=190, 294, etc, or use inst.set_server("hostname") or similar inst . startDSClient () # recommended if running on DS computer; this gets the robot IP from the DS while True : time . sleep ( 1 ) x = x_sub . get () y = y_sub . get () print ( f "X: { x } Y: { y } " ) In this example an instance of NetworkTables is created and subscribers are created to reference the values of “x” and “y” from a table called “datatable”. Then this instance is started as a NetworkTables client with the team number (the roboRIO is always the server). Additionally, if the program is running on the Driver Station computer, by using the startDSClient() method, NetworkTables will get the robot IP address from the Driver Station. Then this sample program simply loops once a second and gets the values for x and y and prints them on the console. In a more realistic program, the client might be processing or generating values for the robot to consume. Building using Gradle Example build.gradle files are provided in the StandaloneAppSamples Repository Update the GradleRIO version to correspond to the desired WPILib version. Java 1 plugins { 2 id "java" 3 id 'application' 4 id 'com.gradleup.shadow' version '8.3.5' 5 id "edu.wpi.first.GradleRIO" version "2025.1.1" 6 id 'edu.wpi.first.WpilibTools' version '2.1.0' 7 } 8 9 application { 10 mainClass = 'Program' 11 } 12 13 wpilibTools . deps . wpilibVersion = wpi . versions . wpilibVersion . get () 14 15 def nativeConfigName = 'wpilibNatives' 16 def nativeConfig = configurations . create ( nativeConfigName ) 17 18 def nativeTasks = wpilibTools . createExtractionTasks { 19 configurationName = nativeConfigName 20 } 21 22 nativeTasks . addToSourceSetResources ( sourceSets . main ) 23 nativeConfig . dependencies . add wpilibTools . deps . wpilib ( "wpimath" ) 24 nativeConfig . dependencies . add wpilibTools . deps . wpilib ( "wpinet" ) 25 nativeConfig . dependencies . add wpilibTools . deps . wpilib ( "wpiutil" ) 26 nativeConfig . dependencies . add wpilibTools . deps . wpilib ( "ntcore" ) 27 nativeConfig . dependencies . add wpilibTools . deps . wpilib ( "cscore" ) 28 nativeConfig . dependencies . add wpilibTools . deps . wpilibOpenCv ( "frc" + wpi . frcYear . get (), wpi . versions . opencvVersion . get ()) 29 30 dependencies { 31 implementation wpilibTools . deps . wpilibJava ( "wpiutil" ) 32 implementation wpilibTools . deps . wpilibJava ( "wpimath" ) 33 implementation wpilibTools . deps . wpilibJava ( "wpinet" ) 34 implementation wpilibTools . deps . wpilibJava ( "ntcore" ) 35 implementation wpilibTools . deps . wpilibJava ( "cscore" ) 36 implementation wpilibTools . deps . wpilibJava ( "cameraserver" ) 37 implementation wpilibTools . deps . wpilibOpenCvJava ( "frc" + wpi . frcYear . get (), wpi . versions . opencvVersion . get ()) 38 39 implementation group: "com.fasterxml.jackson.core" , name: "jackson-annotations" , version: wpi . versions . jacksonVersion . get () 40 implementation group: "com.fasterxml.jackson.core" , name: "jackson-core" , version: wpi . versions . jacksonVersion . get () 41 implementation group: "com.fasterxml.jackson.core" , name: "jackson-databind" , version: wpi . versions . jacksonVersion . get () 42 43 implementation group: "org.ejml" , name: "ejml-simple" , version: wpi . versions . ejmlVersion . get () 44 implementation group: "us.hebi.quickbuf" , name: "quickbuf-runtime" , version: wpi . versions . quickbufVersion . get (); 45 } 46 47 shadowJar { 48 archiveBaseName = "TestApplication" 49 archiveVersion = "" 50 exclude ( "module-info.class" ) 51 archiveClassifier . set ( wpilibTools . currentPlatform . platformName ) 52 } 53 54 wrapper { 55 gradleVersion = '8.11' 56 } C++ Uncomment the appropriate platform as highlighted. 1 plugins { 2 id "cpp" 3 id "edu.wpi.first.GradleRIO" version "2025.1.1" 4 } 5 6 // Disable local cache, as it won't have the cross artifact necessary 7 wpi . maven . useLocal = false 8 9 // Set to true to run simulation in debug mode 10 wpi . cpp . debugSimulation = false 11 12 def appName = "TestApplication" 13 14 //nativeUtils.withCrossLinuxArm64() // Uncomment to build for Linux Arm 64. targetPlatform below also needs to be fixed 15 //nativeUtils.withCrossLinuxArm32() // Uncomment to build for Linux Arm 32. targetPlatform below also needs to be fixed 16 17 model { 18 components { 19 "${appName}" ( NativeExecutableSpec ) { 20 targetPlatform wpi . platforms . desktop // Uncomment to build on whatever the native platform currently is 21 //targetPlatform wpi.platforms.linuxarm64 // Uncomment to build for Linux Arm 64 22 //targetPlatform wpi.platforms.linuxarm32 // Uncomment to build for Linux Arm 32 23 24 sources . cpp { 25 source { 26 srcDir 'src/main/cpp' 27 include '**/*.cpp' , '**/*.cc' 28 } 29 exportedHeaders { 30 srcDir 'src/main/include' 31 } 32 } 33 34 // Enable run tasks for this component 35 wpi . cpp . enableExternalTasks ( it ) 36 37 wpi . cpp . deps . wpilibStatic ( it ) 38 } 39 } 40 } 41 42 wrapper { 43 gradleVersion = '8.11' 44 } Building Python For Python, refer to the RobotPy install documentation .

Listening for Changes A common use case for NetworkTables is where a coprocessor generates values that need to be sent to the robot. For example, imagine that some image processing code running on a coprocessor computes the heading and distance to a goal and sends those values to the robot. In this case it might be desirable for the robot program to be notified when new values arrive. There are a few different ways to detect that a topic’s value has changed; the easiest way is to periodically call a subscriber’s get() , readQueue() , or readQueueValues() function from the robot’s periodic loop, as shown below: Java public class Example { final DoubleSubscriber ySub ; double prev ; public Example () { // get the default instance of NetworkTables NetworkTableInstance inst = NetworkTableInstance . getDefault (); // get the subtable called "datatable" NetworkTable datatable = inst . getTable ( "datatable" ); // subscribe to the topic in "datatable" called "Y" ySub = datatable . getDoubleTopic ( "Y" ). subscribe ( 0.0 ); } public void periodic () { // get() can be used with simple change detection to the previous value double value = ySub . get (); if ( value != prev ) { prev = value ; // save previous value System . out . println ( "X changed value: " + value ); } // readQueueValues() provides all value changes since the last call; // this way it's not possible to miss a change by polling too slowly for ( double iterVal : ySub . readQueueValues ()) { System . out . println ( "X changed value: " + iterVal ); } // readQueue() is similar to readQueueValues(), but provides timestamps // for each change as well for ( TimestampedDouble tsValue : ySub . readQueue ()) { System . out . println ( "X changed value: " + tsValue . value + " at local time " + tsValue . timestamp ); } } // may not be necessary for robot programs if this class lives for // the length of the program public void close () { ySub . close (); } } C++ class Example { nt :: DoubleSubscriber ySub ; double prev = 0 ; public : Example () { // get the default instance of NetworkTables nt :: NetworkTableInstance inst = nt :: NetworkTableInstance :: GetDefault (); // get the subtable called "datatable" auto datatable = inst . GetTable ( "datatable" ); // subscribe to the topic in "datatable" called "Y" ySub = datatable -> GetDoubleTopic ( "Y" ). Subscribe ( 0.0 ); } void Periodic () { // Get() can be used with simple change detection to the previous value double value = ySub . Get (); if ( value != prev ) { prev = value ; // save previous value fmt :: print ( "X changed value: {} 
 " , value ); } // ReadQueueValues() provides all value changes since the last call; // this way it's not possible to miss a change by polling too slowly for ( double iterVal : ySub . ReadQueueValues ()) { fmt :: print ( "X changed value: {} 
 " , iterVal ); } // ReadQueue() is similar to ReadQueueValues(), but provides timestamps // for each change as well for ( nt :: TimestampedDouble tsValue : ySub . ReadQueue ()) { fmt :: print ( "X changed value: {} at local time {} 
 " , tsValue . value , tsValue . timestamp ); } } }; C++ (Handle-based) class Example { NT_Subscriber ySub ; double prev = 0 ; public : Example () { // get the default instance of NetworkTables NT_Inst inst = nt :: GetDefaultInstance (); // subscribe to the topic in "datatable" called "Y" ySub = nt :: Subscribe ( nt :: GetTopic ( inst , "/datatable/Y" ), NT_DOUBLE , "double" ); } void Periodic () { // Get() can be used with simple change detection to the previous value double value = nt :: GetDouble ( ySub , 0.0 ); if ( value != prev ) { prev = value ; // save previous value fmt :: print ( "X changed value: {} 
 " , value ); } // ReadQueue() provides all value changes since the last call; // this way it's not possible to miss a change by polling too slowly for ( nt :: TimestampedDouble value : nt :: ReadQueueDouble ( ySub )) { fmt :: print ( "X changed value: {} at local time {} 
 " , tsValue . value , tsValue . timestamp ); } } }; Python class Example : def __init__ ( self ) -> None : # get the default instance of NetworkTables inst = ntcore . NetworkTableInstance . get_default () # get the subtable called "datatable" datatable = inst . get_table ( "datatable" ) # subscribe to the topic in "datatable" called "Y" self . ySub = datatable . get_double_topic ( "Y" ) . subscribe ( 0.0 ) self . prev = 0 def periodic ( self ): # get() can be used with simple change detection to the previous value value = self . ySub . get () if value != self . prev : self . prev = value # save previous value print ( "X changed value: " + value ) # read_queue() provides all value changes since the last call; # this way it's not possible to miss a change by polling too slowly for ts_value in self . ySub . read_queue (): print ( f "X changed value: { ts_value . value } at local time { ts_value . time } " ) # may not be necessary for robot programs if this class lives for # the length of the program def close ( self ): self . ySub . close () With a command-based robot, it’s also possible to use NetworkBooleanEvent to link boolean topic changes to callback actions (e.g. running commands). While these functions suffice for value changes on a single topic, they do not provide insight into changes to topics (when a topic is published or unpublished, or when a topic’s properties change) or network connection changes (e.g. when a client connects or disconnects). They also don’t provide a way to get in-order updates for value changes across multiple topics. For these needs, NetworkTables provides an event listener facility. The easiest way to use listeners is via NetworkTableInstance . For more automatic control over listener lifetime (particularly in C++), and to operate without a background thread, NetworkTables also provides separate classes for both polled listeners ( NetworkTableListenerPoller ), which store events into an internal queue that must be periodically read to get the queued events, and threaded listeners ( NetworkTableListener ), which call a callback function from a background thread. NetworkTableEvent All listener callbacks take a single NetworkTableEvent parameter, and similarly, reading a listener poller returns an array of NetworkTableEvent . The event contains information including what kind of event it is (e.g. a value update, a new topic, a network disconnect), the handle of the listener that caused the event to be generated, and more detailed information that depends on the type of the event (connection information for connection events, topic information for topic-related events, value data for value updates, and the log message for log message events). Using NetworkTableInstance to Listen for Changes The below example listens to various kinds of events using NetworkTableInstance . The listener callback provided to any of the addListener functions will be called asynchronously from a background thread when a matching event occurs. Warning Because the listener callback is called from a separate background thread, it’s important to use thread-safe synchronization approaches such as mutexes or atomics to pass data to/from the main code and the listener callback function. The addListener functions in NetworkTableInstance return a listener handle. This can be used to remove the listener later. Java public class Example { final DoubleSubscriber ySub ; // use an AtomicReference to make updating the value thread-safe final AtomicReference < Double > yValue = new AtomicReference < Double > (); // retain listener handles for later removal int connListenerHandle ; int valueListenerHandle ; int topicListenerHandle ; public Example () { // get the default instance of NetworkTables NetworkTableInstance inst = NetworkTableInstance . getDefault (); // add a connection listener; the first parameter will cause the // callback to be called immediately for any current connections connListenerHandle = inst . addConnectionListener ( true , event -> { if ( event . is ( NetworkTableEvent . Kind . kConnected )) { System . out . println ( "Connected to " + event . connInfo . remote_id ); } else if ( event . is ( NetworkTableEvent . Kind . kDisconnected )) { System . out . println ( "Disconnected from " + event . connInfo . remote_id ); } }); // get the subtable called "datatable" NetworkTable datatable = inst . getTable ( "datatable" ); // subscribe to the topic in "datatable" called "Y" ySub = datatable . getDoubleTopic ( "Y" ). subscribe ( 0.0 ); // add a listener to only value changes on the Y subscriber valueListenerHandle = inst . addListener ( ySub , EnumSet . of ( NetworkTableEvent . Kind . kValueAll ), event -> { // can only get doubles because it's a DoubleSubscriber, but // could check value.isDouble() here too yValue . set ( event . valueData . value . getDouble ()); }); // add a listener to see when new topics are published within datatable // the string array is an array of topic name prefixes. topicListenerHandle = inst . addListener ( new String [] { datatable . getPath () + "/" }, EnumSet . of ( NetworkTableEvent . Kind . kTopic ), event -> { if ( event . is ( NetworkTableEvent . Kind . kPublish )) { // topicInfo.name is the full topic name, e.g. "/datatable/X" System . out . println ( "newly published " + event . topicInfo . name ); } }); } public void periodic () { // get the latest value by reading the AtomicReference; set it to null // when we read to ensure we only get value changes Double value = yValue . getAndSet ( null ); if ( value != null ) { System . out . println ( "got new value " + value ); } } // may not be needed for robot programs if this class exists for the // lifetime of the program public void close () { NetworkTableInstance inst = NetworkTableInstance . getDefault (); inst . removeListener ( topicListenerHandle ); inst . removeListener ( valueListenerHandle ); inst . removeListener ( connListenerHandle ); ySub . close (); } } C++ class Example { nt :: DoubleSubscriber ySub ; // use a mutex to make updating the value and flag thread-safe wpi :: mutex mutex ; double yValue ; bool yValueUpdated = false ; // retain listener handles for later removal NT_Listener connListenerHandle ; NT_Listener valueListenerHandle ; NT_Listener topicListenerHandle ; public : Example () { // get the default instance of NetworkTables nt :: NetworkTableInstance inst = nt :: NetworkTableInstance :: GetDefault (); // add a connection listener; the first parameter will cause the // callback to be called immediately for any current connections connListenerHandle = inst . AddConnectionListener ( true , [] ( const nt :: Event & event ) { if ( event . Is ( nt :: EventFlags :: kConnected )) { fmt :: print ( "Connected to {} 
 " , event . GetConnectionInfo () -> remote_id ); } else if ( event . Is ( nt :: EventFlags :: kDisconnected )) { fmt :: print ( "Disconnected from {} 
 " , event . GetConnectionInfo () -> remote_id ); } }); // get the subtable called "datatable" auto datatable = inst . GetTable ( "datatable" ); // subscribe to the topic in "datatable" called "Y" ySub = datatable . GetDoubleTopic ( "Y" ). Subscribe ( 0.0 ); // add a listener to only value changes on the Y subscriber valueListenerHandle = inst . AddListener ( ySub , nt :: EventFlags :: kValueAll , [ this ] ( const nt :: Event & event ) { // can only get doubles because it's a DoubleSubscriber, but // could check value.IsDouble() here too std :: scoped_lock lock { mutex }; yValue = event . GetValueData () -> value . GetDouble (); yValueUpdated = true ; }); // add a listener to see when new topics are published within datatable // the string array is an array of topic name prefixes. topicListenerHandle = inst . AddListener ( {{ fmt :: format ( "{}/" , datatable -> GetPath ())}}, nt :: EventFlags :: kTopic , [] ( const nt :: Event & event ) { if ( event . Is ( nt :: EventFlags :: kPublish )) { // name is the full topic name, e.g. "/datatable/X" fmt :: print ( "newly published {} 
 " , event . GetTopicInfo () -> name ); } }); } void Periodic () { // get the latest value by reading the value; set it to false // when we read to ensure we only get value changes wpi :: scoped_lock lock { mutex }; if ( yValueUpdated ) { yValueUpdated = false ; fmt :: print ( "got new value {} 
 " , yValue ); } } ~ Example () { nt :: NetworkTableInstance inst = nt :: NetworkTableInstance :: GetDefault (); inst . RemoveListener ( connListenerHandle ); inst . RemoveListener ( valueListenerHandle ); inst . RemoveListener ( topicListenerHandle ); } }; Python import ntcore import threading class Example : def __init__ ( self ) -> None : # get the default instance of NetworkTables inst = ntcore . NetworkTableInstance . get_default () # Use a mutex to ensure thread safety self . lock = threading . Lock () self . yValue = None # add a connection listener; the first parameter will cause the # callback to be called immediately for any current connections def _connect_cb ( event : ntcore . Event ): if event . is_ ( ntcore . EventFlags . kConnected ): print ( "Connected to" , event . data . remote_id ) elif event . is_ ( ntcore . EventFlags . kDisconnected ): print ( "Disconnected from" , event . data . remote_id ) self . connListenerHandle = inst . add_connection_listener ( True , _connect_cb ) # get the subtable called "datatable" datatable = inst . get_table ( "datatable" ) # subscribe to the topic in "datatable" called "Y" self . ySub = datatable . get_double_topic ( "Y" ) . subscribe ( 0.0 ) # add a listener to only value changes on the Y subscriber def _on_ysub ( event : ntcore . Event ): # can only get doubles because it's a DoubleSubscriber, but # could check value.isDouble() here too with self . lock : self . yValue = event . data . value . get_double () self . valueListenerHandle = inst . add_listener ( self . ySub , ntcore . EventFlags . kValueAll , _on_ysub ) # add a listener to see when new topics are published within datatable # the string array is an array of topic name prefixes. def _on_pub ( event : ntcore . Event ): if event . is_ ( ntcore . EventFlags . kPublish ): # topicInfo.name is the full topic name, e.g. "/datatable/X" print ( "newly published" , event . data . name ) self . topicListenerHandle = inst . add_listener ( [ datatable . getPath () + "/" ], ntcore . EventFlags . kTopic , _on_pub ) def periodic ( self ): # get the latest value by reading the value; set it to null # when we read to ensure we only get value changes with self . lock : value , self . yValue = self . yValue , None if value is not None : print ( "got new value" , value ) # may not be needed for robot programs if this class exists for the # lifetime of the program def close ( self ): inst = ntcore . NetworkTableInstance . get_default () inst . removeListener ( self . topicListenerHandle ) inst . removeListener ( self . valueListenerHandle ) inst . removeListener ( self . connListenerHandle ) self . ySub . close ()
